  `section_description` text DEFAULT NULL,
  `section_order` int(11) NOT NULL,
  `behavior` enum('same-page','next-page') DEFAULT 'same-page'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

