INSERT INTO `form_sections` (`form_section_index`, `form_index`, `section_title`, `section_description`, `section_order`, `behavior`) VALUES
(226, 6, 'Untitled Section', '', 0, 'same-page'),
(238, 7, 'Untitled Section', 'sfdsdfsdfsdf', 1, 'same-page'),
(300, 1, 'Consent', 'This section outlines the terms and conditions regarding the collection, processing, and storage of personal information by the College Guidance and Counseling Center (CGCC) at De La Salle Lipa (DLSL).', 1, 'same-page'),
(301, 1, 'DETAILED CONCERNS', 'The items below describe some of the concerns that students your age might experience. Please check your top five concerns in which the guidance counselor can help you with.', 2, 'same-page'),
(302, 1, 'CLIENT CONSENT FORM', 'This form is a document provided by the CGCC to students in order to properly acquire consent for Counseling. The form contains informalion about the counseling service and the agreement between the counselor and the student.\n\nAPPOINTMENT\nYour sessions are scheduled and agreed upon by you and your counselors. When you need to cancel or reschedule an appointment, please give us at least 24-hours notice.\n\nCOUNSELING and ASSESSMENT\nCounseling is an opportunity to identify and build on current strengths, learn problem-solving strategies, develop or enhance coping skills, learn more effective ways to communicate with others, and receive support and feedback. Assessment is crucial in facilitating the counselor’s understanding of the client. The counseling relationship is designed to be one that will promote change and growth. The counselor and client both have active roles. A record of the counseling and assessment services provided to each client is maintained.\n\nThe goal of the counselor is to provide a comfortable and supportive environment conducive to insight, healing, and personal growth. Your role, as the client, will be to identify goals you would like to achieve during the course of counseling and be willing to examine any potential obstacles and strengths that will either hinder or help you achieve your desired goals.\n\nRISKS\nCounseling and assessment can have benefits and risks and it is important to consider both when making any treatment decisions. Since counseling involves discussing unpleasant aspects of your life, there is a risk that you may experience temporary uncomfortable feelings like sadness, guilt, anger, frustration, loneliness, and helplessness. Disclosing personal information during an assessment may likewise feel uncomfortable and might make you feel vulnerable.\n\nCOUNSELOR CONTACT INFORMATION\nThe primary way to get in touch with us is by contacting your counselor through Canvas or email. If you are in a crisis and need immediate assistance, please go to your nearest emergency room.', 3, 'next-page'),
(303, 1, 'CONFIDENTIALITY and RELEASE of INFORMATION', 'Protecting your privacy is very important. The information in your record is confidential and will not be disclosed to anyone without your written consent unless required by law.\n\nThe exceptions to confidentiality include:\nIf you tell your counselor that you are going to harm or kill yourself or someone else, we are required by law to do whatever we can do to prevent that from happening and to ensure your safety and the safety of others. This may require notifying family members, parents, legal guardians, legal authorities, and/or potential victims.\n\nIf you tell us about incidents of abuse, we are required to report this to proper authorities.\n\nWe are required to release your records if they are subpoenaed by a court of law.\n\nIn addition to the above, there are several other situations where confidentiality cannot be insured, including:\n\nIf you provide us with a request to release your records\n\nIf you are in family counseling, we cannot guarantee confidentiality will be maintained by other family members.\n\nIf you are a child/minor or unable to voluntarily consent, a guardian must give written consent and can access your records.', 4, 'same-page'),
(304, 1, 'USE of CLIENT INFORMATION on OUTCOME RESEARCH', '', 5, 'same-page'),
(305, 8, 'DATA PRIVACY NOTICE', 'All data indicated in this evaluation form are to be kept confidential in compliance with the Republic Act 10173 otherwise known as Data Privacy Act of 2012 and shall only be used for the purpose of evaluating the student experience in counseling. This form shall only be accessed by guidance counselors. CGCC shall retain the data in accordance with Document Retention Period and will be deleted upon disposal. By answering this form, you are giving CGCC consent to process and store this information.', 1, 'same-page'),
(306, 8, 'Counseling Services Evaluation', '', 2, 'next-page'),
(307, 9, 'DATA PRIVACY NOTICE', 'All data indicated in this evaluation form are to be kept confidential in compliance with the Republic Act 10173 otherwise known as Data Privacy Act of 2012 and shall only be used for the purpose of assessing the students\'  general mental health. This form shall only be accessed by guidance counselors. CGCC shall retain the data in accordance with Document Retention Period and will be deleted upon disposal. By answering this form, you are giving CGCC consent to process and store this information.', 1, 'same-page'),
(313, 11, 'EXIT INTERVIEW FORM', '', 1, 'same-page'),
(314, 10, 'College Guidance and Counseling Center - Student Individual Inventory 2024-2025', '', 1, 'same-page'),
(315, 10, 'Personal Information', '', 2, 'same-page'),
(316, 10, 'College Varsity', '', 3, 'next-page'),
(317, 10, 'Family and Home', '', 4, 'same-page'),
(318, 10, 'College Guidance and Counseling Center', '', 5, 'next-page');

