(57, '{\"form_index\":10,\"form_name\":\"Student Individual Inventory\",\"description\":\"This form would only take 15- 20 minutes of your time.\\n\\nEvery person\'s life is a developing story. The person you are today is a result of your upbringing and experiences, joys and sorrows, desires, and dreams. While we know that it\'s tempting to rush at times, please take some time to reflect on your life.\",\"sections\":[{\"id\":284,\"title\":\"College Guidance and Counseling Center - Student Individual Inventory 2024-2025\",\"description\":\"\",\"order\":1,\"behavior\":\"same-page\",\"questions\":[884]},{\"id\":285,\"title\":\"Personal Information\",\"description\":\"\",\"order\":2,\"behavior\":\"same-page\",\"questions\":[885,886,887,888,889,890,891,892,893,894,895,896,897,898]},{\"id\":286,\"title\":\"College Varsity\",\"description\":\"\",\"order\":3,\"behavior\":\"next-page\",\"questions\":[899]},{\"id\":287,\"title\":\"Family and Home\",\"description\":\"\",\"order\":4,\"behavior\":\"same-page\",\"questions\":[900,901,902,903,904,905,906,907,908,909,910,911,912,913,914,915,916]},{\"id\":288,\"title\":\"College Guidance and Counseling Center\",\"description\":\"\",\"order\":5,\"behavior\":\"next-page\",\"questions\":[917,918,919]}],\"questions\":[{\"id\":884,\"question\":\"I understand that this form is considered an official record of De La Salle Lipa and that College Guidance and Counseling Center (CGCC) is required to keep my personal information and records until such time that these documents are due for disposal based on the DLSL data privacy retention policy. Some of the services of CGCC that would utilize this data are Counseling, Referral, and Research and Development. This form shall only be accessed by the CGCC team. CGCC shall retain the data in accordance with Document Retention Period and will be deleted upon disposal. By answering this form, you are giving CGCC consent to process and store this information. Please answer carefully and truthfully.\",\