(59, '{\"form_index\":1,\"form_name\":\"Client Consent and Concern From\",\"description\":\"This form would only take 15- 20 minutes of your time.\\nEvery person\'s life is a developing story. The person you are today is a result of your upbringing and experiences, joys and sorrows, desires, and dreams. While we know that it\'s tempting to rush at times, please take some time to reflect on your life.\",\"sections\":[{\"id\":294,\"title\":\"Consent\",\"description\":\"This section outlines the terms and conditions regarding the collection, processing, and storage of personal information by the College Guidance and Counseling Center (CGCC) at De La Salle Lipa (DLSL).\",\"order\":1,\"behavior\":\"same-page\",\"questions\":[936]},{\"id\":295,\"title\":\"DETAILED CONCERNS\",\"description\":\"The items below describe some of the concerns that students your age might experience. Please check your top five concerns in which the guidance counselor can help you with.\",\"order\":2,\"behavior\":\"same-page\",\"questions\":[937,938,939,940,941,942,943,944,945]},{\"id\":296,\"title\":\"CLIENT CONSENT FORM\",\"description\":\"This form is a document provided by the CGCC to students in order to properly acquire consent for Counseling. The form contains informalion about the counseling service and the agreement between the counselor and the student.\\n\\nAPPOINTMENT\\nYour sessions are scheduled and agreed upon by you and your counselors. When you need to cancel or reschedule an appointment, please give us at least 24-hours notice.\\n\\nCOUNSELING and ASSESSMENT\\nCounseling is an opportunity to identify and build on current strengths, learn problem-solving strategies, develop or enhance coping skills, learn more effective ways to communicate with others, and receive support and feedback. Assessment is crucial in facilitating the counselor\\u2019s understanding of the client. The counseling relationship is designed to be one that will promote change and growth. The counselor and client both have active roles. A record of the counseling and assessment services provided to each client is maintained.\\n\\nThe goal of the counselor is to provide a comfortable and supportive environment conducive to insight, healing, and personal growth. Your role, as the client, will be to identify goals you would like to achieve during the course of counseling and be willing to examine any potential obstacles and strengths that will either hinder or help you achieve your desired goals.\\n\\nRISKS\\nCounseling and assessment can have benefits and risks and it is important to consider both when making any treatment decisions. Since counseling involves discussing unpleasant aspects of your life, there is a risk that you may experience temporary uncomfortable feelings like sadness, guilt, anger, frustration, loneliness, and helplessness. Disclosing personal information during an assessment may likewise feel uncomfortable and might make you feel vulnerable.\\n\\nCOUNSELOR CONTACT INFORMATION\\nThe primary way to get in touch with us is by contacting your counselor through Canvas or email. If you are in a crisis and need immediate assistance, please go to your nearest emergency room.\",\"order\":3,\"behavior\":\"next-page\",\"questions\":[]},{\"id\":297,\"title\":\"CONFIDENTIALITY and RELEASE of INFORMATION\",\"description\":\"Protecting your privacy is very important. The information in your record is confidential and will not be disclosed to anyone without your written consent unless required by law.\\n\\nThe exceptions to confidentiality include:\\nIf you tell your counselor that you are going to harm or kill yourself or someone else, we are required by law to do whatever we can do to prevent that from happening and to ensure your safety and the safety of others. This may require notifying family members, parents, legal guardians, legal authorities, and\\/or potential victims.\\n\\nIf you tell us about incidents of abuse, we are required to report this to proper authorities.\\n\\nWe are required to release your records if they are subpoenaed by a court of law.\\n\\nIn addition to the above, there are several other situations where confidentiality cannot be insured, including:\\n\\nIf you provide us with a request to release your records\\n\\nIf you are in family counseling, we cannot guarantee confidentiality will be maintained by other family members.\\n\\nIf you are a child\\/minor or unable to voluntarily consent, a guardian must give written consent and can access your records.\",\"order\":4,\"behavior\":\"same-page\",\"questions\":[946,947,948]},{\"id\":298,\"title\":\"USE of CLIENT INFORMATION on OUTCOME RESEARCH\",\"description\":\"\",\"order\":5,\"behavior\":\"same-page\",\"questions\":[949,950,951]}],\"questions\":[{\"id\":936,\"question\":\"I understand that this form is considered an official record of De La Salle Lipa and that College Guidance and Counseling Center (CGCC) is required to keep my personal information and records until such time that these documents are due for disposal based on the DLSL data privacy retention policy. Some of the services of CGCC that would utilize this data are Counseling, Referral, and Research and Development. This form shall only be accessed by the CGCC team. CGCC shall retain the data in accordance with Document Retention Period and will be deleted upon disposal. By answering this form, you are giving CGCC consent to process and store this information. Please answer carefully and truthfully.\",\"type\":\"checkbox\",\"subtype\":null,\"required\":true,\"options\":[{\"choice_index\":4955,\"choice_text\":\"Yes\"}],\"rows\":[],\"form_section_index\":294},{\"id\":937,\"question\":\"SOCIAL\\/EMOTIONAL CONCERNS\",\"type\":\"checkbox\",\"subtype\":null,\"required\":true,\"options\":[{\"choice_index\":4956,\"choice_text\":\"Adjusting to change\"},{\"choice_index\":4957,\"choice_text\":\"Experiencing Bullying\\/Discrimination\"},{\"choice_index\":4958,\"choice_text\":\"Struggling with Relationship Problems\"},{\"choice_index\":4959,\"choice_text\":\"Issues with self-image\"},{\"choice_index\":4960,\"choice_text\":\"Concerns about sexuality\\/gender identity\"},{\"choice_index\":4961,\"choice_text\":\"Finding it difficult to express one\'s thoughts\\/feelings\"},{\"choice_index\":4962,\"choice_text\":\"Struggling in getting along with others\\/making friends\"},{\"choice_index\":4963,\"choice_text\":\"Spiritual\\/Religious issues\"},{\"choice_index\":4964,\"choice_text\":\"Lack of decision making skills\"},{\"choice_index\":4965,\"choice_text\":\"Lack of social support\"},{\"choice_index\":4966,\"choice_text\":\"Lacking of self-confidence\"},{\"choice_index\":4967,\"choice_text\":\"Lacks effective communication skills\"},{\"choice_index\":4968,\"choice_text\":\"Need to develop leadership skills\"},{\"choice_index\":4969,\"choice_text\":\"Need to have better self-concept\"},{\"choice_index\":4970,\"choice_text\":\"Experiencing harassment\"},{\"choice_index\":4971,\"choice_text\":\"Trust issue\"},{\"choice_index\":4972,\"choice_text\":\"Feeling very strong emotions\"},{\"choice_index\":4973,\"choice_text\":\"No social\\/emotional concern\"}],\"rows\":[],\"form_section_index\":295},{\"id\":938,\"question\":\"FAMILY & HOME CONCERNS\",\"type\":\"checkbox\",\"subtype\":null,\"required\":true,\"options\":[{\"choice_index\":4974,\"choice_text\":\"Absence of father\\/mother\"},{\"choice_index\":4975,\"choice_text\":\"Dealing with a loss\"},{\"choice_index\":4976,\"choice_text\":\"Feeling of being unloved\"},{\"choice_index\":4977,\"choice_text\":\"Financial difficulties\"},{\"choice_index\":4978,\"choice_text\":\"Struggling with parents\\u2019 marital conflicts\\/separationz\"},{\"choice_index\":4979,\"choice_text\":\"Health of a family member\"},{\"choice_index\":4980,\"choice_text\":\"Home environment is not conducive to study\"},{\"choice_index\":4981,\"choice_text\":\"Homesickness\\/Living away from home\"},{\"choice_index\":4982,\"choice_text\":\"Lacking parents\' appreciation\"},{\"choice_index\":4983,\"choice_text\":\"Not getting along well with a family member\\/relative\"},{\"choice_index\":4984,\"choice_text\":\"Feeling pressured by high expectations from parents\\/family\"},{\"choice_index\":4985,\"choice_text\":\"Feeling invalidated by family members\"},{\"choice_index\":4986,\"choice_text\":\"Concerned about the health of a family member\"},{\"choice_index\":4987,\"choice_text\":\"Too many responsibilities at home\"},{\"choice_index\":4988,\"choice_text\":\"No Family\\/Home Concern\"}],\"rows\":[],\"form_section_index\":295},{\"id\":939,\"question\":\"MENTAL\\/PHYSICAL HEALTH CONCERNS\",\"type\":\"checkbox\",\"subtype\":null,\"required\":true,\"options\":[{\"choice_index\":4989,\"choice_text\":\"Struggling with addiction (substance use, internet, gaming, gambling, shopping)\"},{\"choice_index\":4990,\"choice_text\":\"Difficulty in managing emotions\"},{\"choice_index\":4991,\"choice_text\":\"Feeling burned out\"},{\"choice_index\":4992,\"choice_text\":\"Feeling tired\\/fatigued most of the time (physically\\/emotionally)\"},{\"choice_index\":4993,\"choice_text\":\"Having a physical illness that needs medical attention\"},{\"choice_index\":4994,\"choice_text\":\"Racing thoughts\"},{\"choice_index\":4995,\"choice_text\":\"Overthinking \\/ Anxiety\"},{\"choice_index\":4996,\"choice_text\":\"Having panic attacks\"},{\"choice_index\":4997,\"choice_text\":\"Experiencing stress\"},{\"choice_index\":4998,\"choice_text\":\"Difficulty coping with stress\"},{\"choice_index\":4999,\"choice_text\":\"Deep feelings of sadness\"},{\"choice_index\":5000,\"choice_text\":\"Self-harm behavior (cutting, scratching, burning, etc.)\"},{\"choice_index\":5001,\"choice_text\":\"Erratic sleeping patterns\"},{\"choice_index\":5002,\"choice_text\":\"Suicidal thoughts\"},{\"choice_index\":5003,\"choice_text\":\"Suicide attempt\"},{\"choice_index\":5004,\"choice_text\":\"Difficulty concentrating\\/being more forgetful\"},{\"choice_index\":5005,\"choice_text\":\"Avoiding people, situations, or responsibilities\"},{\"choice_index\":5006,\"choice_text\":\"Unable to enjoy\\/loss of interest in activities\"},{\"choice_index\":5007,\"choice_text\":\"Feeling empty\\/Not feeling anything\"},{\"choice_index\":5008,\"choice_text\":\"Increased irritability\"},{\"choice_index\":5009,\"choice_text\":\"Crying spells\"},{\"choice_index\":5010,\"choice_text\":\"Changes in appetite (eating more or less)\"},{\"choice_index\":5011,\"choice_text\":\"No Mental\\/Physical Health Concerns\"}],\"rows\":[],\"form_section_index\":295},{\"id\":940,\"question\":\"ACADEMIC CONCERNS\",\"type\":\"checkbox\",\"subtype\":null,\"required\":true,\"options\":[{\"choice_index\":5012,\"choice_text\":\"Difficulty in adjusting to learning modality\"},{\"choice_index\":5013,\"choice_text\":\"Difficulty in meeting academic requirements\"},{\"choice_index\":5014,\"choice_text\":\"Difficulty working independently\"},{\"choice_index\":5015,\"choice_text\":\"Difficulty working in a group\\/pair\"},{\"choice_index\":5016,\"choice_text\":\"Dissatisfaction with academic performance\\/grades\"},{\"choice_index\":5017,\"choice_text\":\"Lacking effective study habits (note-taking, time management)\"},{\"choice_index\":5018,\"choice_text\":\"Difficulty overcoming distractions\"},{\"choice_index\":5019,\"choice_text\":\"Lacking motivation\"},{\"choice_index\":5020,\"choice_text\":\"Struggling with procrastination\"},{\"choice_index\":5021,\"choice_text\":\"Struggling to balance academics with extracurricular\\/non-academic activities\"},{\"choice_index\":5022,\"choice_text\":\"Test anxiety\"},{\"choice_index\":5023,\"choice_text\":\"No Academic concern\"}],\"rows\":[],\"form_section_index\":295},{\"id\":941,\"question\":\"PROFESSOR ISSUE CONCERNS\",\"type\":\"checkbox\",\"subtype\":null,\"required\":true,\"options\":[{\"choice_index\":5024,\"choice_text\":\"Favoritism\\/ unfair treatment\"},{\"choice_index\":5025,\"choice_text\":\"Inadequate background knowledge about the subjects\"},{\"choice_index\":5026,\"choice_text\":\"Unavailable most of the time\"},{\"choice_index\":5027,\"choice_text\":\"Difficult to reach or communicate with\"},{\"choice_index\":5028,\"choice_text\":\"Unethical\\/unprofessional behavior\"},{\"choice_index\":5029,\"choice_text\":\"Does not provide timely feedback\"},{\"choice_index\":5030,\"choice_text\":\"No Professor issues\\/concerns\"}],\"rows\":[],\"form_section_index\":295},{\"id\":942,\"question\":\"CAREER CONCERNS\",\"type\":\"checkbox\",\"subtype\":null,\"required\":true,\"options\":[{\"choice_index\":5031,\"choice_text\":\"Uncertainty about career choice\\/ wanting to shift to another program\"},{\"choice_index\":5032,\"choice_text\":\"Career choice is limited by financial resources\"},{\"choice_index\":5033,\"choice_text\":\"Unaware of strengths, abilities, or interests\"},{\"choice_index\":5034,\"choice_text\":\"Feeling lost and overwhelmed about making a career decision\"},{\"choice_index\":5035,\"choice_text\":\"Feeling pressured by peers\\/family to succeed\"},{\"choice_index\":5036,\"choice_text\":\"Need help with career planning\"},{\"choice_index\":5037,\"choice_text\":\"Dissatisfied with the present college program\"},{\"choice_index\":5038,\"choice_text\":\"Anxious about the future\\/world of work\"},{\"choice_index\":5039,\"choice_text\":\"No Career concern\"}],\"rows\":[],\"form_section_index\":295},{\"id\":943,\"question\":\"I have other concerns\\/questions that I want to directly consult or discuss with my counselor.\",\"type\":\"multiple\",\"subtype\":null,\"required\":true,\"options\":[{\"choice_index\":5040,\"choice_text\":\"Yes\"},{\"choice_index\":5041,\"choice_text\":\"No\"}],\"rows\":[],\"form_section_index\":295},{\"id\":944,\"question\":\"We appreciate your feedback. Please let us know how we can best improve our CGCC Student Individual Inventory (SII) Form. If you have comments\\/suggestions, please indicate them below:\",\"type\":\"short\",\"subtype\":\"text\",\"required\":true,\"options\":[],\"rows\":[],\"form_section_index\":295},{\"id\":945,\"question\":\"By submitting this form, I certify that the above information are true and correct. FALSIFICATION of any information will be subjected to DISCIPLINARY ACTION.\",\"type\":\"checkbox\",\"subtype\":null,\"required\":true,\"options\":[{\"choice_index\":5042,\"choice_text\":\"I Certify\"}],\"rows\":[],\"form_section_index\":295},{\"id\":946,\"question\":\"I understand the nature and limits of confidentiality stated above and accept them as part of the benefits and conditions of participating in counseling. In the event that my counselor reasonably believes that there is evidence of clear and imminent danger of harm to myself and\\/or others, physically or emotionally, I give consent to my counselor to contact the following persons, in addition to the school and medical personnel.\",\"type\":\"multiple\",\"subtype\":null,\"required\":true,\"options\":[{\"choice_index\":5043,\"choice_text\":\"Agree\"},{\"choice_index\":5044,\"choice_text\":\"Disagree\"}],\"rows\":[],\"form_section_index\":297},{\"id\":947,\"question\":\"Name of Father\\/Mother or Legal Guardian\",\"type\":\"short\",\"subtype\":\"text\",\"required\":true,\"options\":[],\"rows\":[],\"form_section_index\":297},{\"id\":948,\"question\":\"Contact number of parent\\/guardian\",\"type\":\"short\",\"subtype\":\"text\",\"required\":true,\"options\":[],\"rows\":[],\"form_section_index\":297},{\"id\":949,\"question\":\"When client information is utilized on outcome research purposes, client names are not disclosed.\",\"type\":\"multiple\",\"subtype\":null,\"required\":true,\"options\":[{\"choice_index\":5045,\"choice_text\":\"I allow the College Guidance and Counseling Center to use the data from my record for outcome research given that my identity is protected.\"},{\"choice_index\":5046,\"choice_text\":\"I do not allow the College Guidance and Counseling Center to use the data from my record for outcome research.\"}],\"rows\":[],\"form_section_index\":298},{\"id\":950,\"question\":\"Counseling Guidelines\\nPlease review the Counseling Guidelines through this link: https:\\/\\/bit.ly\\/counselingguide\\nBy accomplishing this form you understand and agree to the guidelines set by CGCC.\",\"type\":\"display\",\"subtype\":null,\"required\":false,\"options\":[],\"rows\":[],\"form_section_index\":298},{\"id\":951,\"question\":\"This document has provided the information required to address expectations about counseling. I have read and fully understand this document. All questions that I had have been answered to my satisfaction. By filling out this form, I voluntarily agree to accept counseling.\",\"type\":\"display\",\"subtype\":null,\"required\":false,\"options\":[],\"rows\":[],\"form_section_index\":298}],\"timestamp\":\"2025-05-31T07:19:39+02:00\"}', 1, '2025-05-31 05:19:39', 0),
