estion_index\":127,\"sub_question_text\":\"Leadership skills\"},{\"sub_question_index\":128,\"sub_question_text\":\"Capacity to understand current world issues\"},{\"sub_question_index\":129,\"sub_question_text\":\"Capacity to understand human diversity (cultural diversity, sexual diversity, etc.)\"},{\"sub_question_index\":130,\"sub_question_text\":\"Capacity to access relevant and trustworthy information\"}],\"form_section_index\":299},{\"id\":956,\"question\":\"What are your next plans regarding education and career\",\"type\":\"checkbox\",\"subtype\":null,\"required\":true,\"options\":[{\"choice_index\":5060,\"choice_text\":\"Continue with graduate studies in the same field\"},{\"choice_index\":5061,\"choice_text\":\"Continue with graduate studies in a different field\"},{\"choice_index\":5062,\"choice_text\":\"Continue with higher education in another field\"},{\"choice_index\":5063,\"choice_text\":\"Review for Licensure Examination\"},{\"choice_index\":5064,\"choice_text\":\"Look for a job\"},{\"choice_index\":5065,\"choice_text\":\"I already have a job and will immediately start working\"},{\"choice_index\":5066,\"choice_text\":\"Involve myself with volunteer activities\"},{\"choice_index\":5067,\"choice_text\":\"Help manage our family business\"},{\"choice_index\":5068,\"choice_text\":\"Work on an online job\"},{\"choice_index\":5069,\"choice_text\":\"Stay unemployed and rest for a while\"},{\"choice_index\":5070,\"choice_text\":\"Other\"}],\"rows\":[],\"form_section_index\":299},{\"id\":957,\"question\":\"What are your worries\\/concerns now that you are graduating from college?\",\"type\":\"checkbox\",\"subtype\":null,\"required\":true,\"options\":[{\"choice_index\":5071,\"choice_text\":\"Feels unprepared for job application process (job interview, creating a resume, visiting companies, etc.)\"},{\"choice_index\":5072,\"choice_text\":\"Feels not ready for the world of work\"},{\"choice_index\":5073,\"choice_text\":\"Anxious about competition in job hunting