alle Lipa as an academic institution\"},{\"sub_question_index\":132,\"sub_question_text\":\"To enroll my college program in De La Salle Lipa.\"},{\"sub_question_index\":133,\"sub_question_text\":\"To enroll in other college programs in De La Salle Lipa\"}],\"form_section_index\":299},{\"id\":959,\"question\":\"Overall comments in your stay in De La Salle Lipa.\",\"type\":\"short\",\"subtype\":\"\",\"required\":false,\"options\":[],\"rows\":[],\"form_section_index\":299}],\"timestamp\":\"2025-05-31T07:32:09+02:00\"}', 11, '2025-05-31 05:32:09', 0);
INSERT INTO `form_snapshots` (`snapshot_index`, `snapshot_data`, `form_index`, `created_at`, `is_active`) VALUES
(61, '{\"form_index\":1,\"form_name\":\"Client Consent and Concern From\",\"description\":\"This form would only take 15- 20 minutes of your time.\\nEvery person\'s life is a developing story. The person you are today is a result of your upbringing and experiences, joys and sorrows, desires, and dreams. While we know that it\'s tempting to rush at times, please take some time to reflect on your life.\",\"sections\":[{\"id\":300,\"title\":\"Consent\",\"description\":\"This section outlines the terms and conditions regarding the collection, processing, and storage of personal information by the College Guidance and Counseling Center (CGCC) at De La Salle Lipa (DLSL).\",\"order\":1,\"behavior\":\"same-page\",\"questions\":[{\"id\":960,\"question\":\"I understand that this form is considered an official record of De La Salle Lipa and that College Guidance and Counseling Center (CGCC) is required to keep my personal information and records until such time that these documents are due for disposal based on the DLSL data privacy retention policy. Some of the services of CGCC that would utilize this data are Counseling, Referral, and Research and Development. This form shall only be accessed by the CGCC team. CGCC shall retain the data in accordance with Document Retention Period and will be deleted upon disposal. By answering this form, you are giving CGCC consent to process and store this information. Please answer carefully and truthfully.\",\"type\":\"checkbox\",\"subtype\":null,\"required\":true,\"options\":[{\"choice_index\":5082,\"choice_text\":\"Yes\"}],\"rows\":[],\"form_section_index\":300}]},{\"id\":301,\"title\":\"DETAILED CONCERNS\",\"description\":\"The items below describe some of the concerns that students your age might experience. Please check your top five concerns in which the guidance counselor can help you with.\",\"order\":2,\"behavior\":\"same-page\",\"questions\":[{\"id\":961,\"question\":\"SOCIAL\\/EMOTIONAL CONCERNS\",\"type\":\"checkbox\",\"subtype\":null,\"required\":true,\"options\":[{\"choice_index\":5083,\"choice_text\":\"Adjusting to change\"},{\"choice_index\":5084,\"choice_text\":\"Experiencing Bullying\\/Discrimination\"},{\"choice_index\":5085,\"choice_text\":\"Struggling with Relationship Problems\"},{\"choice_index\":5086,\"choice_text\":\"Issues with self-image\"},{\"choice_index\":5087,\"choice_text\":\"Concerns about sexuality\\/gender identity\"},{\"choice_index\":5088,\"choice_text\":\"Finding it difficult to express one\'s thoughts\\/feelings\"},{\"choice_index\":5089,\"choice_text\":\"Struggling in getting along with others\\/making friends\"},{\"choice_index\":5090,\"choice_text\":\"Spiritual\\/Religious issues\"},{\"choice_index\":5091,\"choice_text\":\"Lack of decision making skills\"},{\"choice_index\":5092,\"choice_text\":\"Lack of social support\"},{\"choice_index\":5093,\"choice_text\":\"Lacking of self-confidence\"},{\"choice_index\":5094,\"choice_text\":\"Lacks effective communication skills\"},{\"choice_index\":5095,\"choice_text\":\"Need to develop leadership skills\"},{\"choice_index\":5096,\"choice_text\":\"Need to have better self-concept\"},{\"choice_index\":5097,\"choice_text\":\"Experiencing harassment\"},{\"choice_index\":5098,\"choice_text\":\"Trust issue\"},{\"choice_index\":5099,\"choice_text\":\"Feeling very strong emotions\"},{\"choice_index\":5100,\"choice_text\":\"No social\\/emotional concern\"}],\"rows\":[],\"form_section_index\":301},{\"id\":962,\"question\":\"FAMILY & HOME CONCERNS\",\"type\":\"checkbox\",\"subtype\":null,\"required\":true,\"options\":[{\"choice_index\":5101,\"choice_text\":\"Absence of father\\/mother\"},{\"choice_index\":5102,\"choice_text\":\"Dealing with a loss\"},{\"choice_index\":5103,\"choice_text\":\"Feeling of being unloved\"},{\"choice_index\":5104,\"choice_text\":\"Financial difficulties\"},{\"choice_index\":5105,\"choice_text\":\"Struggling with parents\\u2019 marital conflicts\\/separationz\"},{\"choice_index\":5106,\"choice_text\":\"Health of a family member\"},{\"choice_index\":5107,\"choice_text\":\"Home environment is not conducive to study\"},{\"choice_index\":5108,\"choice_text\":\"Homesickness\\/Living away from home\"},{\"choice_index\":5109,\"choice_text\":\"Lacking parents\' appreciation\"},{\"choice_index\":5110,\"choice_text\":\"Not getting along well with a family member\\/relative\"},{\"choice_index\":5111,\"choice_text\":\"Feeling pressured by high expectations from parents\\/family\"},{\"choice_index\":5112,\"choice_text\":\"Feeling invalidated by family members\"},{\"choice_index\":5113,\"choice_text\":\"Concerned about the health of a family member\"},{\"choice_index\":5114,\"choice_text\":\"Too many responsibilities at home\"},{\"choice_index\":5115,\"choice_text\":\"No Family\\/Home Concern\"}],\"rows\":[],\"form_section_index\":301},{\"id\":963,\"question\":\"MENTAL\\/PHYSICAL HEALTH CONCERNS\",\"type\":\"checkbox\",\"subtype\":null,\"required\":true,\"options\":[{\"choice_index\":5116,\"choice_text\":\"Struggling with addiction (substance use, internet, gaming, gambling, shopping)\"},{\"choice_index\":5117,\"choice_text\":\"Difficulty in managing emotions\"},{\"choice_index\":5118,\"choice_text\":\"Feeling burned out\"},{\"choice_index\":5119,\"choice_text\":\"Feeling tired\\/fatigued most of the time (physically\\/emotionally)\"},{\"choice_index\":5120,\"choice_text\":\"Having a physical illness that needs medical attention\"},{\"choice_index\":5121,\"choice_text\":\"Racing thoughts\"},{\"choice_index\":5122,\"choice_text\":\"Overthinking \\/ Anxiety\"},{\"choice_index\":5123,\"choice_text\":\"Having panic attacks\"},{\"choice_index\":5124,\"choice_text\":\"Experiencing stress\"},{\"choice_index\":5125,\"choice_text\":\"Difficulty coping with stress\"},{\"choice_index\":5126,\"choice_text\":\"Deep feelings of sadness\"},{\"choice_index\":5127,\"choice_text\":\"Self-harm behavior (cutting, scratching, burning, etc.)\"},{\"choice_index\":5128,\"choice_text\":\"Erratic sleeping patterns\"},{\"choice_index\":5129,\"choice_text\":\"Suicidal thoughts\"},{\"choice_index\":5130,\"choice_text\":\"Suicide attempt\"},{\"choice_index\":5131,\"choice_text\":\"Difficulty concentrating\\/being more forgetful\"},{\"choice_index\":5132,\"choice_text\":\"Avoiding people, situations, or responsibilities\"},{\"choice_index\":5133,\"choice_text\":\"Unable to enjoy\\/loss of interest in activities\"},{\"choice_index\":5134,\"choice_text\":\"Feeling empty\\/Not feeling anything\"},{\"choice_index\":5135,\"choice_text\":\"Increased irritability\"},{\"choice_index\":5136,\"choice_text\":\"Crying spells\"},{\"choice_index\":5137,\"choice_text\":\"Changes in appetite (eating more or less)\"},{\"choice_index\":5138,\"choice_text\":\"No Mental\\/Physical Health Concerns\"}],\"rows\":[],\"form_section_index\":301},{\"id\":964,\"question\":\"ACADEMIC CONCERNS\",\"type\":\"checkbox\",\"subtype\":null,\"required\":true,\"options\":[{\"choice_index\":5139,\"choice_text\":\"Difficulty in adjusting to learning modality\"},{\"choice_index\":5140,\"choice_text\":\"Difficulty in meeting academic requirements\"},{\"choice_index\":5141,\"choice_text\":\"Difficulty working independently\"},{\"choice_index\":5142,\"choice_text\":\"Difficulty working in a group\\/pair\"},{\"choice_index\":5143,\"choice_text\":\"Dissatisfaction with academic performance\\/grades\"},{\"choice_index\":5144,\"choice_text\":\"Lacking effective study habits (note-taking, time management)\"},{\"choice_index\":5145,\"choice_text\":\"Difficulty overcoming distractions\"},{\"choice_index\":5146,\"choice_text\":\"Lacking motivation\"},{\"choice_index\":5147,\"choice_text\":\"Struggling with procrastination\"},{\"choice_index\":5148,\"choice_text\":\"Struggling to balance academics with extracurricular\\/non-academic activities\"},{\"choice_index\":5149,\"choice_text\":\"Test anxiety\"},{\"choice_index\":5150,\"choice_text\":\"No Academic concern\"}],\"rows\":[],\"form_section_index\":301},{\"id\":965,\"question\":\"PROFESSOR ISSUE CONCERNS\",\"type\":\"checkbox\",\"subtype\":null,\"required\":true,\"options\":[{\"choice_index\":5151,\"choice_text\":\"Favoritism\\/ unfair treatment\"},{\"choice_index\":5152,\"choice_text\":\"Inadequate background knowledge about the subjects\"},{\"choice_index\":5153,\"choice_text\":\"Unavailable most of the time\"},{\"choice_index\":5154,\"choice_text\":\"Difficult to reach or communicate with\"},{\"choice_index\":5155,\"choice_text\":\"Unethical\\/unprofessional behavior\"},{\"choice_index\":5156,\"choice_text\":\"Does not provide timely feedback\"},{\"choice_index\":5157,\"choice_text\":\"No Professor issues\\/concerns\"}],\"rows\":[],\"form_section_index\":301},{\"id\":966,\"question\":\"CAREER CONCERNS\",\"type\":\"checkbox\",\"subtype\":null,\"required\":true,\"options\":[{\"choice_index\":5158,\"choice_text\":\"Uncertainty about career choice\\/ wanting to shift to another program\"},{\"choice_index\":5159,\"choice_text\":\"Career choice is limited by financial resources\"},{\"choice_index\":5160,\"choice_text\":\"Unaware of strengths, abilities, or interests\"},{\"choice_index\":5161,\"choice_text\":\"Feeling lost and overwhelmed about making a career decision\"},{\"choice_index\":5162,\"choice_text\":\"Feeling pressured by peers\\/family to succeed\"},{\"choice_index\":5163,\"choice_text\":\"Need help with career planning\"},{\"choice_index\":5164,\"choice_text\":\"Dissatisfied with the present college program\"},{\"choice_index\":5165,\"choice_text\":\"Anxious about the future\\/world of work\"},{\"choice_index\":5166,\"choice_text\":\"No Career concern\"}],\"rows\":[],\"form_section_index\":301},{\"id\":967,\"question\":\"I have other concerns\\/questions that I want to directly consult or discuss with my counselor.\",\"type\":\"multiple\",\"subtype\":null,\"required\":true,\"options\":[{\"choice_index\":5167,\"choice_text\":\"Yes\"},{\"choice_index\":5168,\"choice_text\":\"No\"}],\"rows\":[],\"form_section_index\":301},{\"id\":968,\"question\":\"We appreciate your feedback. Please let us know how we can best improve our CGCC Student Individual Inventory (SII) Form. If you have comments\\/suggestions, please indicate them below:\",\"type\":\"short\",\"subtype\":\"text\",\"required\":true,\"options\":[],\"rows\":[],\"form_section_index\":301},{\"id\":969,\"question\":\"By submitting this form, I certify that the above information are true and correct. FALSIFICATION of any information will be subjected to DISCIPLINARY ACTION.\",\"type\":\"checkbox\",\"subtype\":null,\"required\":true,\"options\":[{\"choice_index\":5169,\"choice_text\":\"I Certify\"}],\"rows\":[],\"form_section_index\":301}]},{\"id\":302,\"title\":\"CLIENT CONSENT FORM\",\"description\":\"This form is a document provided by the CGCC to students in order to properly acquire consent for Counseling. The form contains informalion about the counseling service and the agreement between the counselor and the student.\\n\\nAPPOINTMENT\\nYour sessions are scheduled and agreed upon by you and your counselors. When you need to cancel or reschedule an appointment, please give us at least 24-hours notice.\\n\\nCOUNSELING and ASSESSMENT\\nCounseling is an opportunity to identify and build on current strengths, learn problem-solving strategies, develop or enhance coping skills, learn more effective ways to communicate with others, and receive support and feedback. Assessment is crucial in facilitating the counselor\\u2019s understanding of the client. The counseling relationship is designed to be one that will promote change and growth. The counselor and client both have active roles. A record of the counseling and assessment services provided to each client is maintained.\\n\\nThe goal of the counselor is to provide a comfortable and supportive environment conducive to insight, healing, and personal growth. Your role, as the client, will be to identify goals you would like to achieve during the course of counseling and be willing to examine any potential obstacles and strengths that will either hinder or help you achieve your desired goals.\\n\\nRISKS\\nCounseling and assessment can have benefits and risks and it is important to consider both when making any treatment decisions. Since counseling involves discussing unpleasant aspects of your life, there is a risk that you may experience temporary uncomfortable feelings like sadness, guilt, anger, frustration, loneliness, and helplessness. Disclosing personal information during an assessment may likewise feel uncomfortable and might make you feel vulnerable.\\n\\nCOUNSELOR CONTACT INFORMATION\\nThe primary way to get in touch with us is by contacting your counselor through Canvas or email. If you are in a crisis and need immediate assistance, please go to your nearest emergency room.\",\"order\":3,\"behavior\":\"next-page\",\"questions\":[]},{\"id\":303,\"title\":\"CONFIDENTIALITY and RELEASE of INFORMATION\",\"description\":\"Protecting your privacy is very important. The information in your record is confidential and will not be disclosed to anyone without your written consent unless required by law.\\n\\nThe exceptions to confidentiality include:\\nIf you tell your counselor that you are going to harm or kill yourself or someone else, we are required by law to do whatever we can do to prevent that from happening and to ensure your safety and the safety of others. This may require notifying family members, parents, legal guardians, legal authorities, and\\/or potential victims.\\n\\nIf you tell us about incidents of abuse, we are required to report this to proper authorities.\\n\\nWe are required to release your records if they are subpoenaed by a court of law.\\n\\nIn addition to the above, there are several other situations where confidentiality cannot be insured, including:\\n\\nIf you provide us with a request to release your records\\n\\nIf you are in family counseling, we cannot guarantee confidentiality will be maintained by other family members.\\n\\nIf you are a child\\/minor or unable to voluntarily consent, a guardian must give written consent and can access your records.\",\"order\":4,\"behavior\":\"same-page\",\"questions\":[{\"id\":970,\"question\":\"I understand the nature and limits of confidentiality stated above and accept them as part of the benefits and conditions of participating in counseling. In the event that my counselor reasonably believes that there is evidence of clear and imminent danger of harm to myself and\\/or others, physically or emotionally, I give consent to my counselor to contact the following persons, in addition to the school and medical personnel.\",\"type\":\"multiple\",\"subtype\":null,\"required\":true,\"options\":[{\"choice_index\":5170,\"choice_text\":\"Agree\"},{\"choice_index\":5171,\"choice_text\":\"Disagree\"}],\"rows\":[],\"form_section_index\":303},{\"id\":971,\"question\":\"Name of Father\\/Mother or Legal Guardian\",\"type\":\"short\",\"subtype\":\"text\",\"required\":true,\"options\":[],\"rows\":[],\"form_section_index\":303},{\"id\":972,\"question\":\"Contact number of parent\\/guardian\",\"type\":\"short\",\"subtype\":\"text\",\"required\":true,\"options\":[],\"rows\":[],\"form_section_index\":303}]},{\"id\":304,\"title\":\"USE of CLIENT INFORMATION on OUTCOME RESEARCH\",\"description\":\"\",\"order\":5,\"behavior\":\"same-page\",\"questions\":[{\"id\":973,\"question\":\"When client information is utilized on outcome research purposes, client names are not disclosed.\",\"type\":\"multiple\",\"subtype\":null,\"required\":true,\"options\":[{\"choice_index\":5172,\"choice_text\":\"I allow the College Guidance and Counseling Center to use the data from my record for outcome research given that my identity is protected.\"},{\"choice_index\":5173,\"choice_text\":\"I do not allow the College Guidance and Counseling Center to use the data from my record for outcome research.\"}],\"rows\":[],\"form_section_index\":304},{\"id\":974,\"question\":\"Counseling Guidelines\\nPlease review the Counseling Guidelines through this link: https:\\/\\/bit.ly\\/counselingguide\\nBy accomplishing this form you understand and agree to the guidelines set by CGCC.\",\"type\":\"display\",\"subtype\":null,\"required\":false,\"options\":[],\"rows\":[],\"form_section_index\":304},{\"id\":975,\"question\":\"This document has provided the information required to address expectations about counseling. I have read and fully understand this document. All questions that I had have been answered to my satisfaction. By filling out this form, I voluntarily agree to accept counseling.\",\"type\":\"display\",\"subtype\":null,\"required\":false,\"options\":[],\"rows\":[],\"form_section_index\":304}]}],\"questions\":[{\"id\":960,\"question\":\"I understand that this form is considered an official record of De La Salle Lipa and that College Guidance and Counseling Center (CGCC) is required to keep my personal information and records until such time that these documents are due for disposal based on the DLSL data privacy retention policy. Some of the services of CGCC that would utilize this data are Counseling, Referral, and Research and Development. This form shall only be accessed by the CGCC team. CGCC shall retain the data in accordance with Document Retention Period and will be deleted upon disposal. By answering this form, you are giving CGCC consent to process and store this information. Please answer carefully and truthfully.\",\"type\":\"checkbox\",\"subtype\":null,\"required\":true,\"options\":[{\"choice_index\":5082,\"choice_text\":\"Yes\"}],\"rows\":[],\"form_section_index\":300},{\"id\":961,\"question\":\"SOCIAL\\/EMOTIONAL CONCERNS\",\"type\":\"checkbox\",\"subtype\":null,\"required\":true,\"options\":[{\"choice_index\":5083,\"choice_text\":\"Adjusting to change\"},{\"choice_index\":5084,\"choice_text\":\"Experiencing Bullying\\/Discrimination\"},{\"choice_index\":5085,\"choice_text\":\"Struggling with Relationship Problems\"},{\"choice_index\":5086,\"choice_text\":\"Issues with self-image\"},{\"choice_index\":5087,\"choice_text\":\"Concerns about sexuality\\/gender identity\"},{\"choice_index\":5088,\"choice_text\":\"Finding it difficult to express one\'s thoughts\\/feelings\"},{\"choice_index\":5089,\"choice_text\":\"Struggling in getting along with others\\/making friends\"},{\"choice_index\":5090,\"choice_text\":\"Spiritual\\/Religious issues\"},{\"choice_index\":5091,\"choice_text\":\"Lack of decision making skills\"},{\"choice_index\":5092,\"choice_text\":\"Lack of social support\"},{\"choice_index\":5093,\"choice_text\":\"Lacking of self-confidence\"},{\"choice_index\":5094,\"choice_text\":\"Lacks effective communication skills\"},{\"choice_index\":5095,\"choice_text\":\"Need to develop leadership skills\"},{\"choice_index\":5096,\"choice_text\":\"Need to have better self-concept\"},{\"choice_index\":5097,\"choice_text\":\"Experiencing harassment\"},{\"choice_index\":5098,\"choice_text\":\"Trust issue\"},{\"choice_index\":5099,\"choice_text\":\"Feeling very strong emotions\"},{\"choice_index\":5100,\"choice_text\":\"No social\\/emotional concern\"}],\"rows\":[],\"form_section_index\":301},{\"id\":962,\"question\":\"FAMILY & HOME CONCERNS\",\"type\":\"checkbox\",\"subtype\":null,\"required\":true,\"options\":[{\"choice_index\":5101,\"choice_text\":\"Absence of father\\/mother\"},{\"choice_index\":5102,\"choice_text\":\"Dealing with a loss\"},{\"choice_index\":5103,\"choice_text\":\"Feeling of being unloved\"},{\"choice_index\":5104,\"choice_text\":\"Financial difficulties\"},{\"choice_index\":5105,\"choice_text\":\"Struggling with parents\\u2019 marital conflicts\\/separationz\"},{\"choice_index\":5106,\"choice_text\":\"Health of a family member\"},{\"choice_index\":5107,\"choice_text\":\"Home environment is not conducive to study\"},{\"choice_index\":5108,\"choice_text\":\"Homesickness\\/Living away from home\"},{\"choice_index\":5109,\"choice_text\":\"Lacking parents\' appreciation\"},{\"choice_index\":5110,\"choice_text\":\"Not getting along well with a family member\\/relative\"},{\"choice_index\":5111,\"choice_text\":\"Feeling pressured by high expectations from parents\\/family\"},{\"choice_index\":5112,\"choice_text\":\"Feeling invalidated by family members\"},{\"choice_index\":5113,\"choice_text\":\"Concerned about the health of a family member\"},{\"choice_index\":5114,\"choice_text\":\"Too many responsibilities at home\"},{\"choice_index\":5115,\"choice_text\":\"No Family\\/Home Concern\"}],\"rows\":[],\"form_section_index\":301},{\"id\":963,\"question\":\"MENTAL\\/PHYSICAL HEALTH CONCERNS\",\"type\":\"checkbox\",\"subtype\":null,\"required\":true,\"options\":[{\"choice_index\":5116,\"choice_text\":\"Struggling with addiction (substance use, internet, gaming, gambling, shopping)\"},{\"choice_index\":5117,\"choice_text\":\"Difficulty in managing emotions\"},{\"choice_index\":5118,\"choice_text\":\"Feeling burned out\"},{\"choice_index\":5119,\"choice_text\":\"Feeling tired\\/fatigued most of the time (physically\\/emotionally)\"},{\"choice_index\":5120,\"choice_text\":\"Having a physical illness that needs medical attention\"},{\"choice_index\":5121,\"choice_text\":\"Racing thoughts\"},{\"choice_index\":5122,\"choice_text\":\"Overthinking \\/ Anxiety\"},{\"choice_index\":5123,\"choice_text\":\"Having panic attacks\"},{\"choice_index\":5124,\"choice_text\":\"Experiencing stress\"},{\"choice_index\":5125,\"choice_text\":\"Difficulty coping with stress\"},{\"choice_index\":5126,\"choice_text\":\"Deep feelings of sadness\"},{\"choice_index\":5127,\"choice_text\":\"Self-harm behavior (cutting, scratching, burning, etc.)\"},{\"choice_index\":5128,\"choice_text\":\"Erratic sleeping patterns\"},{\"choice_index\":5129,\"choice_text\":\"Suicidal thoughts\"},{\"choice_index\":5130,\"choice_text\":\"Suicide attempt\"},{\"choice_index\":5131,\"choice_text\":\"Difficulty concentrating\\/being more forgetful\"},{\"choice_index\":5132,\"choice_text\":\"Avoiding people, situations, or responsibilities\"},{\"choice_index\":5133,\"choice_text\":\"Unable to enjoy\\/loss of interest in activities\"},{\"choice_index\":5134,\"choice_text\":\"Feeling empty\\/Not feeling anything\"},{\"choice_index\":5135,\"choice_text\":\"Increased irritability\"},{\"choice_index\":5136,\"choice_text\":\"Crying spells\"},{\"choice_index\":5137,\"choice_text\":\"Changes in appetite (eating more or less)\"},{\"choice_index\":5138,\"choice_text\":\"No Mental\\/Physical Health Concerns\"}],\"rows\":[],\"form_section_index\":301},{\"id\":964,\"question\":\"ACADEMIC CONCERNS\",\"type\":\"checkbox\",\"subtype\":null,\"required\":true,\"options\":[{\"choice_index\":5139,\"choice_text\":\"Difficulty in adjusting to learning modality\"},{\"choice_index\":5140,\"choice_text\":\"Difficulty in meeting academic requirements\"},{\"choice_index\":5141,\"choice_text\":\"Difficulty working independently\"},{\"choice_index\":5142,\"choice_text\":\"Difficulty working in a group\\/pair\"},{\"choice_index\":5143,\"choice_text\":\"Dissatisfaction with academic performance\\/grades\"},{\"choice_index\":5144,\"choice_text\":\"Lacking effective study habits (note-taking, time management)\"},{\"choice_index\":5145,\"choice_text\":\"Difficulty overcoming distractions\"},{\"choice_index\":5146,\"choice_text\":\"Lacking motivation\"},{\"choice_index\":5147,\"choice_text\":\"Struggling with procrastination\"},{\"choice_index\":5148,\"choice_text\":\"Struggling to balance academics with extracurricular\\/non-academic activities\"},{\"choice_index\":5149,\"choice_text\":\"Test anxiety\"},{\"choice_index\":5150,\"choice_text\":\"No Academic concern\"}],\"rows\":[],\"form_section_index\":301},{\"id\":965,\"question\":\"PROFESSOR ISSUE CONCERNS\",\"type\":\"checkbox\",\"subtype\":null,\"required\":true,\"options\":[{\"choice_index\":5151,\"choice_text\":\"Favoritism\\/ unfair treatment\"},{\"choice_index\":5152,\"choice_text\":\"Inadequate background knowledge about the subjects\"},{\"choice_index\":5153,\"choice_text\":\"Unavailable most of the time\"},{\"choice_index\":5154,\"choice_text\":\"Difficult to reach or communicate with\"},{\"choice_index\":5155,\"choice_text\":\"Unethical\\/unprofessional behavior\"},{\"choice_index\":5156,\"choice_text\":\"Does not provide timely feedback\"},{\"choice_index\":5157,\"choice_text\":\"No Professor issues\\/concerns\"}],\"rows\":[],\"form_section_index\":301},{\"id\":966,\"question\":\"CAREER CONCERNS\",\"type\":\"checkbox\",\"subtype\":null,\"required\":true,\"options\":[{\"choice_index\":5158,\"choice_text\":\"Uncertainty about career choice\\/ wanting to shift to another program\"},{\"choice_index\":5159,\"choice_text\":\"Career choice is limited by financial resources\"},{\"choice_index\":5160,\"choice_text\":\"Unaware of strengths, abilities, or interests\"},{\"choice_index\":5161,\"choice_text\":\"Feeling lost and overwhelmed about making a career decision\"},{\"choice_index\":5162,\"choice_text\":\"Feeling pressured by peers\\/family to succeed\"},{\"choice_index\":5163,\"choice_text\":\"Need help with career planning\"},{\"choice_index\":5164,\"choice_text\":\"Dissatisfied with the present college program\"},{\"choice_index\":5165,\"choice_text\":\"Anxious about the future\\/world of work\"},{\"choice_index\":5166,\"choice_text\":\"No Career concern\"}],\"rows\":[],\"form_section_index\":301},{\"id\":967,\"question\":\"I have other concerns\\/questions that I want to directly consult or discuss with my counselor.\",\"type\":\"multiple\",\"subtype\":null,\"required\":true,\"options\":[{\"choice_index\":5167,\"choice_text\":\"Yes\"},{\"choice_index\":5168,\"choice_text\":\"No\"}],\"rows\":[],\"form_section_index\":301},{\"id\":968,\"question\":\"We appreciate your feedback. Please let us know how we can best improve our CGCC Student Individual Inventory (SII) Form. If you have comments\\/suggestions, please indicate them below:\",\"type\":\"short\",\"subtype\":\"text\",\"required\":true,\"options\":[],\"rows\":[],\"form_section_index\":301},{\"id\":969,\"question\":\"By submitting this form, I certify that the above information are true and correct. FALSIFICATION of any information will be subjected to DISCIPLINARY ACTION.\",\"type\":\"checkbox\",\"subtype\":null,\"required\":true,\"options\":[{\"choice_index\":5169,\"choice_text\":\"I Certify\"}],\"rows\":[],\"form_section_index\":301},{\"id\":970,\"question\":\"I understand the nature and limits of confidentiality stated above and accept them as part of the benefits and conditions of participating in counseling. In the event that my counselor reasonably believes that there is evidence of clear and imminent danger of harm to myself and\\/or others, physically or emotionally, I give consent to my counselor to contact the following persons, in addition to the school and medical personnel.\",\"type\":\"multiple\",\"subtype\":null,\"required\":true,\"options\":[{\"choice_index\":5170,\"choice_text\":\"Agree\"},{\"choice_index\":5171,\"choice_text\":\"Disagree\"}],\"rows\":[],\"form_section_index\":303},{\"id\":971,\"question\":\"Name of Father\\/Mother or Legal Guardian\",\"type\":\"short\",\"subtype\":\"text\",\"required\":true,\"options\":[],\"rows\":[],\"form_section_index\":303},{\"id\":972,\"question\":\"Contact number of parent\\/guardian\",\"type\":\"short\",\"subtype\":\"text\",\"required\":true,\"options\":[],\"rows\":[],\"form_section_index\":303},{\"id\":973,\"question\":\"When client information is utilized on outcome research purposes, client names are not disclosed.\",\"type\":\"multiple\",\"subtype\":null,\"required\":true,\"options\":[{\"choice_index\":5172,\"choice_text\":\"I allow the College Guidance and Counseling Center to use the data from my record for outcome research given that my identity is protected.\"},{\"choice_index\":5173,\"choice_text\":\"I do not allow the College Guidance and Counseling Center to use the data from my record for outcome research.\"}],\"rows\":[],\"form_section_index\":304},{\"id\":974,\"question\":\"Counseling Guidelines\\nPlease review the Counseling Guidelines through this link: https:\\/\\/bit.ly\\/counselingguide\\nBy accomplishing this form you understand and agree to the guidelines set by CGCC.\",\"type\":\"display\",\"subtype\":null,\"required\":false,\"options\":[],\"rows\":[],\"form_section_index\":304},{\"id\":975,\"question\":\"This document has provided the information required to address expectations about counseling. I have read and fully understand this document. All questions that I had have been answered to my satisfaction. By filling out this form, I voluntarily agree to accept counseling.\",\"type\":\"display\",\"subtype\":null,\"required\":false,\"options\":[],\"rows\":[],\"form_section_index\":304}],\"timestamp\":\"2025-05-31T23:14:32+02:00\"}', 1, '2025-05-31 21:14:32', 1),
(62, '{\"form_index\":8,\"form_name\":\"Counseling Service Evaluation Form\",\"description\":\"COUNSELING SERVICE EVALUATION\\n\\nIn order for us to continuously evaluate and improve our counseling services, we would like to get feedback from you on your experience in your counseling session.\",\"sections\":[{\"id\":305,\"title\":\"DATA PRIVACY NOTICE\",\"description\":\"All data indicated in this evaluation form are to be kept confidential in compliance with the Republic Act 10173 otherwise known as Data Privacy Act of 2012 and shall only be used for the purpose of evaluating the student experience in counseling. This form shall only be accessed by guidance counselors. CGCC shall retain the data in accordance with Document Retention Period and will be deleted upon disposal. By answering this form, you are giving CGCC consent to process and store this information.\",\"order\":1,\"behavior\":\"same-page\",\"questions\":[{\"id\":976,\"question\":\"Counselor being Evaluated\",\"type\":\"dropdown\",\"subtype\":null,\"required\":true,\"options\":[{\"choice_index\":5174,\"choice_text\":\"Ms. Jane Aira Ramilo\"},{\"choice_index\":5175,\"choice_text\":\"Ms. Nery Dumol\"},{\"choice_index\":5176,\"choice_text\":\"Ms. Geraldine Flores\"},{\"choice_index\":5177,\"choice_text\":\"Ms. Lot Prospero\"},{\"choice_index\":5178,\"choice_text\":\"Ms. Olive Diokno\"},{\"choice_index\":5179,\"choice_text\":\"Ms. Mercy Malabanan\"},{\"choice_index\":5180,\"choice_text\":\"Ms. Edchell Adajar\"},{\"choice_index\":5181,\"choice_text\":\"Ms. Kristine Mendoza\"}],\"rows\":[],\"form_section_index\":305}]},{\"id\":306,\"title\":\"Counseling Services Evaluation\",\"description\":\"\",\"order\":2,\"behavior\":\"next-page\",\"questions\":[{\"id\":977,\"question\":\"Please choose the number that corresponds to your level of agreement to the following statements (4 being the HIGHEST and 1 being the LOWEST):\",\"type\":\"grid\",\"subtype\":null,\"required\":true,\"options\":[{\"choice_index\":5182,\"choice_text\":\"4 - Strongly Agree\"},{\"choice_index\":5183,\"choice_text\":\"3 - Agree\"},{\"choice_index\":5184,\"choice_text\":\"2 - Disagree\"},{\"choice_index\":5185,\"choice_text\":\"1 - Strongly Agree\"}],\"rows\":[\"The counselor understood my social\\/emotional, academic, and career-related concerns and provided useful information and assistance.\",\"I felt comfortable with my counselor\",\"I was able to express my thoughts and feelings effectively to my counselor.\",\"The counselor actively listened to me.\",\"The counselor provided professional and courteous assistance.\",\"The counselor is always available.\",\"Provides a venue for private confidential counseling sessions.\",\"The time allotted for the session was sufficient.\",\"Seeing the counselor was worth my time.\",\"Overall, I was satisfied with the counseling session.\"],\"form_section_index\":306},{\"id\":978,\"question\":\"Please take this opportunity to express your comments and suggestion about your experience with this session. We encourage you to be completely open, as this is the only way we can evaluate ourselves and initiate improvements.\",\"type\":\"paragraph\",\"subtype\":null,\"required\":false,\"options\":[],\"rows\":[],\"form_section_index\":306},{\"id\":979,\"question\":\"Thank you!\\n\\nWe appreciate your comments and feedback.\",\"type\":\"display\",\"subtype\":null,\"required\":false,\"options\":[],\"rows\":[],\"form_section_index\":306}]}],\"questions\":[{\"id\":976,\"question\":\"Counselor being Evaluated\",\"type\":\"dropdown\",\"subtype\":null,\"required\":true,\"options\":[{\"choice_index\":5174,\"choice_text\":\"Ms. Jane Aira Ramilo\"},{\"choice_index\":5175,\"choice_text\":\"Ms. Nery Dumol\"},{\"choice_index\":5176,\"choice_text\":\"Ms. Geraldine Flores\"},{\"choice_index\":5177,\"choice_text\":\"Ms. Lot Prospero\"},{\"choice_index\":5178,\"choice_text\":\"Ms. Olive Diokno\"},{\"choice_index\":5179,\"choice_text\":\"Ms. Mercy Malabanan\"},{\"choice_index\":5180,\"choice_text\":\"Ms. Edchell Adajar\"},{\"choice_index\":5181,\"choice_text\":\"Ms. Kristine Mendoza\"}],\"rows\":[],\"form_section_index\":305},{\"id\":977,\"question\":\"Please choose the number that corresponds to your level of agreement to the following statements (4 being the HIGHEST and 1 being the LOWEST):\",\"type\":\"grid\",\"subtype\":null,\"required\":true,\"options\":[{\"choice_index\":5182,\"choice_text\":\"4 - Strongly Agree\"},{\"choice_index\":5183,\"choice_text\":\"3 - Agree\"},{\"choice_index\":5184,\"choice_text\":\"2 - Disagree\"},{\"choice_index\":5185,\"choice_text\":\"1 - Strongly Agree\"}],\"rows\":[\"The counselor understood my social\\/emotional, academic, and career-related concerns and provided useful information and assistance.\",\"I felt comfortable with my counselor\",\"I was able to express my thoughts and feelings effectively to my counselor.\",\"The counselor actively listened to me.\",\"The counselor provided professional and courteous assistance.\",\"The counselor is always available.\",\"Provides a venue for private confidential counseling sessions.\",\"The time allotted for the session was sufficient.\",\"Seeing the counselor was worth my time.\",\"Overall, I was satisfied with the counseling session.\"],\"form_section_index\":306},{\"id\":978,\"question\":\"Please take this opportunity to express your comments and suggestion about your experience with this session. We encourage you to be completely open, as this is the only way we can evaluate ourselves and initiate improvements.\",\"type\":\"paragraph\",\"subtype\":null,\"required\":false,\"options\":[],\"rows\":[],\"form_section_index\":306},{\"id\":979,\"question\":\"Thank you!\\n\\nWe appreciate your comments and feedback.\",\"type\":\"display\",\"subtype\":null,\"required\":false,\"options\":[],\"rows\":[],\"form_section_index\":306}],\"timestamp\":\"2025-05-31T23:14:37+02:00\"}', 8, '2025-05-31 21:14:37', 1),
(63, '{\"form_index\":9,\"form_name\":\"General Mental Health Screening\",\"description\":\"This form intends to determine your current mental health status based on your experience in the past two (2) weeks. This information would allow your counselor to better assist you with your concerns.\\n\\n*DSM-5-TR Self-Rated Level 1 Cross-Cutting Symptom Measure, American Psychiatric Association\",\"sections\":[{\"id\":307,\"title\":\"DATA PRIVACY NOTICE\",\"description\":\"All data indicated in this evaluation form are to be kept confidential in compliance with the Republic Act 10173 otherwise known as Data Privacy Act of 2012 and shall only be used for the purpose of assessing the students\'  general mental health. This form shall only be accessed by guidance counselors. CGCC shall retain the data in accordance with Document Retention Period and will be deleted upon disposal. By answering this form, you are giving CGCC consent to process and store this information.\",\"order\":1,\"behavior\":\"same-page\",\"questions\":[{\"id\":980,\"question\":\"\",\"type\":\"grid\",\"subtype\":null,\"required\":false,\"options\":[{\"choice_index\":5186,\"choice_text\":\"Not at all\"},{\"choice_index\":5187,\"choice_text\":\"Rare, less than a day or two\"},{\"choice_index\":5188,\"choice_text\":\"Several days\"},{\"choice_index\":5189,\"choice_text\":\"Most of the days in the past 2 weeks\"},{\"choice_index\":5190,\"choice_text\":\"Almost everyday\"}],\"rows\":[\"Worried about your health or about getting sick\",\"Been bothered by not being able to fall asleep or stay asleep, or by waking up too early\",\"Been bothered by not being able to focus when you were in class or doing homework\\/reading a book\\/playing a game\",\"Had less fun doing things than you used to\",\"Felt sad or depressed for several hours\",\"Felt more irritated or easily annoyed than usual\",\"Felt angry or lost your temper\",\"Feeling nervous, anxious, or scared\",\"Not been able to stop worrying\",\"Not been able to do things you wanted to or should have done, because they made you feel nervous\",\"Little interest or pleasure in doing things\"],\"form_section_index\":307},{\"id\":981,\"question\":\"In the past two (2) weeks, have you:\",\"type\":\"grid\",\"subtype\":null,\"required\":false,\"options\":[{\"choice_index\":5191,\"choice_text\":\"Yes\"},{\"choice_index\":5192,\"choice_text\":\"No\"}],\"rows\":[\"Had an alcoholic beverage (beer, wine, liquor, etc)?\",\"Smoked a cigarette\\/vape?\",\"Used prohibited drugs?\",\"Used any medicine without a doctor\\u2019s prescription to get high or change the way you feel?\",\"Have you thought about ending your life or committing suicide?\",\"Have you EVER tried to kill yourself?\"],\"form_section_index\":307},{\"id\":982,\"question\":\"Sometimes things happen to people that are unusually or especially frightening, horrible, or traumatic. For example a serious accident or fire, a physical or sexual assault or abuse, an earthquake or flood, a war, seeing someone be killed or seriously injured, having a loved one die through homicide or suicide. Have you ever experienced any of this kind of event?\",\"type\":\"multiple\",\"subtype\":null,\"required\":false,\"options\":[{\"choice_index\":5193,\"choice_text\":\"Yes\"},{\"choice_index\":5194,\"choice_text\":\"No\"}],\"rows\":[],\"form_section_index\":307},{\"id\":983,\"question\":\"How would you rate your current level of stress?\",\"type\":\"multiple\",\"subtype\":null,\"required\":false,\"options\":[{\"choice_index\":5195,\"choice_text\":\"Very Low\"},{\"choice_index\":5196,\"choice_text\":\"Low\"},{\"choice_index\":5197,\"choice_text\":\"Moderate\"},{\"choice_index\":5198,\"choice_text\":\"High\"},{\"choice_index\":5199,\"choice_text\":\"Very High\"}],\"rows\":[],\"form_section_index\":307},{\"id\":984,\"question\":\"Suicide Risk Screening\\/Assessment (Please respond to the following items)\",\"type\":\"grid\",\"subtype\":null,\"required\":true,\"options\":[{\"choice_index\":5200,\"choice_text\":\"Yes\"},{\"choice_index\":5201,\"choice_text\":\"No\"}],\"rows\":[\"I have thoughts about killing myself in the last 7 days.\",\"I wish I could go to sleep and never wake up.\",\"I feel hopeless about my current situation.\",\"I have taken steps to prepare to end my life\",\"I have tried inflicting harm to myself within the last 7 days.\",\"I am thinking about harming or killing someone.\",\"I had suicidal attempts\"],\"form_section_index\":307},{\"id\":985,\"question\":\"Thanks for answering the questions above. At this point, we would like to know if there are other things that you would like to share or talk about with your counselor.\",\"type\":\"paragraph\",\"subtype\":null,\"required\":false,\"options\":[],\"rows\":[],\"form_section_index\":307}]}],\"questions\":[{\"id\":980,\"question\":\"\",\"type\":\"grid\",\"subtype\":null,\"required\":false,\"options\":[{\"choice_index\":5186,\"choice_text\":\"Not at all\"},{\"choice_index\":5187,\"choice_text\":\"Rare, less than a day or two\"},{\"choice_index\":5188,\"choice_text\":\"Several days\"},{\"choice_index\":5189,\"choice_text\":\"Most of the days in the past 2 weeks\"},{\"choice_index\":5190,\"choice_text\":\"Almost everyday\"}],\"rows\":[\"Worried about your health or about getting sick\",\"Been bothered by not being able to fall asleep or stay asleep, or by waking up too early\",\"Been bothered by not being able to focus when you were in class or doing homework\\/reading a book\\/playing a game\",\"Had less fun doing things than you used to\",\"Felt sad or depressed for several hours\",\"Felt more irritated or easily annoyed than usual\",\"Felt angry or lost your temper\",\"Feeling nervous, anxious, or scared\",\"Not been able to stop worrying\",\"Not been able to do things you wanted to or should have done, because they made you feel nervous\",\"Little interest or pleasure in doing things\"],\"form_section_index\":307},{\"id\":981,\"question\":\"In the past two (2) weeks, have you:\",\"type\":\"grid\",\"subtype\":null,\"required\":false,\"options\":[{\"choice_index\":5191,\"choice_text\":\"Yes\"},{\"choice_index\":5192,\"choice_text\":\"No\"}],\"rows\":[\"Had an alcoholic beverage (beer, wine, liquor, etc)?\",\"Smoked a cigarette\\/vape?\",\"Used prohibited drugs?\",\"Used any medicine without a doctor\\u2019s prescription to get high or change the way you feel?\",\"Have you thought about ending your life or committing suicide?\",\"Have you EVER tried to kill yourself?\"],\"form_section_index\":307},{\"id\":982,\"question\":\"Sometimes things happen to people that are unusually or especially frightening, horrible, or traumatic. For example a serious accident or fire, a physical or sexual assault or abuse, an earthquake or flood, a war, seeing someone be killed or seriously injured, having a loved one die through homicide or suicide. Have you ever experienced any of this kind of event?\",\"type\":\"multiple\",\"subtype\":null,\"required\":false,\"options\":[{\"choice_index\":5193,\"choice_text\":\"Yes\"},{\"choice_index\":5194,\"choice_text\":\"No\"}],\"rows\":[],\"form_section_index\":307},{\"id\":983,\"question\":\"How would you rate your current level of stress?\",\"type\":\"multiple\",\"subtype\":null,\"required\":false,\"options\":[{\"choice_index\":5195,\"choice_text\":\"Very Low\"},{\"choice_index\":5196,\"choice_text\":\"Low\"},{\"choice_index\":5197,\"choice_text\":\"Moderate\"},{\"choice_index\":5198,\"choice_text\":\"High\"},{\"choice_index\":5199,\"choice_text\":\"Very High\"}],\"rows\":[],\"form_section_index\":307},{\"id\":984,\"question\":\"Suicide Risk Screening\\/Assessment (Please respond to the following items)\",\"type\":\"grid\",\"subtype\":null,\"required\":true,\"options\":[{\"choice_index\":5200,\"choice_text\":\"Yes\"},{\"choice_index\":5201,\"choice_text\":\"No\"}],\"rows\":[\"I have thoughts about killing myself in the last 7 days.\",\"I wish I could go to sleep and never wake up.\",\"I feel hopeless about my current situation.\",\"I have taken steps to prepare to end my life\",\"I have tried inflicting harm to myself within the last 7 days.\",\"I am thinking about harming or killing someone.\",\"I had suicidal attempts\"],\"form_section_index\":307},{\"id\":985,\"question\":\"Thanks for answering the questions above. At this point, we would like to know if there are other things that you would like to share or talk about with your counselor.\",\"type\":\"paragraph\",\"subtype\":null,\"required\":false,\"options\":[],\"rows\":[],\"form_section_index\":307}],\"timestamp\":\"2025-05-31T23:14:43+02:00\"}', 9, '2025-05-31 21:14:43', 1);
INSERT INTO `form_snapshots` (`snapshot_index`, `snapshot_data`, `form_index`, `created_at`, `is_active`) VALUES
(64, '{\"form_index\":10,\"form_name\":\"Student Individual Inventory\",\"description\":\"This form would only take 15- 20 minutes of your time.\\n\\nEvery person\'s life is a developing story. The person you are today is a result of your upbringing and experiences, joys and sorrows, desires, and dreams. While we know that it\'s tempting to rush at times, please take some time to reflect on your life.\",\"sections\":[{\"id\":308,\"title\":\"College Guidance and Counseling Center - Student Individual Inventory 2024-2025\",\"description\":\"\",\"order\":1,\"behavior\":\"same-page\",\"questions\":[{\"id\":986,\"question\":\"I understand that this form is considered an official record of De La Salle Lipa and that College Guidance and Counseling Center (CGCC) is required to keep my personal information and records until such time that these documents are due for disposal based on the DLSL data privacy retention policy. Some of the services of CGCC that would utilize this data are Counseling, Referral, and Research and Development. This form shall only be accessed by the CGCC team. CGCC shall retain the data in accordance with Document Retention Period and will be deleted upon disposal. By answering this form, you are giving CGCC consent to process and store this information. Please answer carefully and truthfully.\",\"type\":\"display\",\"subtype\":null,\"required\":false,\"options\":[],\"rows\":[],\"form_section_index\":308}]},{\"id\":309,\"title\":\"Personal Information\",\"description\":\"\",\"order\":2,\"behavior\":\"same-page\",\"questions\":[{\"id\":987,\"question\":\"Nickname\",\"type\":\"short\",\"subtype\":\"text\",\"required\":true,\"options\":[],\"rows\":[],\"form_section_index\":309},{\"id\":988,\"question\":\"Last school attended during SHS                              \\n2nd Year - 5th Year College students, Put N\\/A\",\"type\":\"short\",\"subtype\":\"text\",\"required\":true,\"options\":[],\"rows\":[],\"form_section_index\":309},{\"id\":989,\"question\":\