(65, '{\"form_index\":11,\"form_name\":\"EXIT INTERVIEW FORM\",\"description\":\"This form is designed for graduating students to evaluate various aspects of their academic and campus experience. It collects feedback on: Academic Quality (courses, faculty, resources), Campus Life (facilities, extracurriculars, support services), Career Preparation (internships, counseling, skill development), and Overall Satisfaction. Responses help the institution improve programs and services for future students.\",\"sections\":[{\"id\":313,\"title\":\"EXIT INTERVIEW FORM\",\"description\":\"\",\"order\":1,\"behavior\":\"same-page\",\"questions\":[{\"id\":1022,\"question\":\"How would you evaluate the overall quality of your college experience at De La Salle Lipa?\",\"type\":\"multiple\",\"subtype\":null,\"required\":true,\"options\":[{\"choice_index\":5255,\"choice_text\":\"Very Good\"},{\"choice_index\":5256,\"choice_text\":\"Good\"},{\"choice_index\":5257,\"choice_text\":\"Poor\"},{\"choice_index\":5258,\"choice_text\":\"Very Poor\"}],\"rows\":[],\"form_section_index\":313},{\"id\":1023,\"question\":\"How satisfied are you with the following aspects that De La Salle Lipa has provided?\",\"type\":\"grid\",\"subtype\":null,\"required\":true,\"options\":[{\"choice_index\":5259,\"choice_text\":\"Very Satisfied\"},{\"choice_index\":5260,\"choice_text\":\"Satisfied\"},{\"choice_index\":5261,\"choice_text\":\"Dissatisfied\"},{\"choice_index\":5262,\"choice_text\":\"Not Satisfied\"},{\"choice_index\":5263,\"choice_text\":\"N\\/A\"}],\"rows\":[\"Teachers\",\"Curriculum\",\"Quality of academic advising\",\"Quality of teaching modules\",\"Quality of practice\\/OJT opportunities (e.g. facilitating access to internships))\",\"Overall usefulness of De La Salle Lipa\\u2019s website\",\"Quality of library resources and services\",\"Quality of enrollment process and services\",\"Quality of payment process\",\"Viewing of grades\",\"Quality of services in acquiring copy of student records (e.g. copy of grades etc.)\",\"Overall value of the education with respect to tuition fee\",\"Quality of online academic-related engagements with students\",\"Quality of activities of student organizations\",\"Quality of student government plans and programs\",\"Campus safety and security services\",\"Student Formation and Discipline Office services\",\"Institutional Lasallian Formation Office (ILFO) services\",\"Lasallian Assistance Management Program (LAMP) services\",\"Quality of Institutional Health Services (Clinic)\",\"College Guidance and Counseling Center services\"],\"form_section_index\":313},{\"id\":1024,\"question\":\"Please share any comments about your level of satisfaction with the services above (optional).\",\"type\":\"short\",\"subtype\":\"text\",\"required\":false,\"options\":[],\"rows\":[],\"form_section_index\":313},{\"id\":1025,\"question\":\"How would you evaluate the following learning results that you have gained at the end of this College Experience?\",\"type\":\"grid\",\"subtype\":null,\"required\":true,\"options\":[{\"choice_index\":5264,\"choice_text\":\"Very Good\"},{\"choice_index\":5265,\"choice_text\":\"Good\"},{\"choice_index\":5266,\"choice_text\":\"Poor\"},{\"choice_index\":5267,\"choice_text\":\"Very Poor\"}],\"rows\":[\"General preparation for life\",\"Competence in your major field of study\",\"Foundation for graduate studies\",\"Critical thinking skills\",\"Quantitative reasoning skills\",\"Written communication skills\",\"Oral communication skills\",\"Leadership skills\",\"Capacity to understand current world issues\",\"Capacity to understand human diversity (cultural diversity, sexual diversity, etc.)\",\"Capacity to access relevant and trustworthy information\"],\"form_section_index\":313},{\"id\":1026,\"question\":\"What are your next plans regarding education and career\",\"type\":\"checkbox\",\"subtype\":null,\"required\":true,\"options\":[{\"choice_index\":5268,\"choice_text\":\"Continue with graduate studies in the same field