(66, '{\"form_index\":10,\"form_name\":\"Student Individual Inventory\",\"description\":\"This form would only take 15- 20 minutes of your time.\\n\\nEvery person\'s life is a developing story. The person you are today is a result of your upbringing and experiences, joys and sorrows, desires, and dreams. While we know that it\'s tempting to rush at times, please take some time to reflect on your life.\",\"sections\":[{\"id\":314,\"title\":\"College Guidance and Counseling Center - Student Individual Inventory 2024-2025\",\"description\":\"\",\"order\":1,\"behavior\":\"same-page\",\"questions\":[{\"id\":1030,\"question\":\"I understand that this form is considered an official record of De La Salle Lipa and that College Guidance and Counseling Center (CGCC) is required to keep my personal information and records until such time that these documents are due for disposal based on the DLSL data privacy retention policy. Some of the services of CGCC that would utilize this data are Counseling, Referral, and Research and Development. This form shall only be accessed by the CGCC team. CGCC shall retain the data in accordance with Document Retention Period and will be deleted upon disposal. By answering this form, you are giving CGCC consent to process and store this information. Please answer carefully and truthfully.\",\"type\":\"display\",\"subtype\":null,\"required\":false,\"options\":[],\"rows\":[],\"form_section_index\":314}]},{\"id\":315,\"title\":\"Personal Information\",\"description\":\"\",\"order\":2,\"behavior\":\"same-page\",\"questions\":[{\"id\":1031,\"question\":\"Nickname\",\"type\":\"short\",\"subtype\":\"text\",\"required\":true,\"options\":[],\"rows\":[],\"form_section_index\":315},{\"id\":1032,\"question\":\"Last school attended during SHS                              \\n2nd Year - 5th Year College students, Put N\\/A\",\"type\":\"short\",\"subtype\":\"text\",\"required\":true,\"options\":[],\"rows\":[],\"form_section_index\":315},{\"id\":1033,\"question