INSERT INTO `main_questions` (`main_question_index`, `form_index`, `main_question_text`, `type_index`, `subtype`, `is_required`, `form_section_index`) VALUES
(710, 6, 'dfgdgdfg', 1, '', 0, 226),
(722, 7, 'number', 1, '', 0, 238),
(960, 1, 'I understand that this form is considered an official record of De La Salle Lipa and that College Guidance and Counseling Center (CGCC) is required to keep my personal information and records until such time that these documents are due for disposal based on the DLSL data privacy retention policy. Some of the services of CGCC that would utilize this data are Counseling, Referral, and Research and Development. This form shall only be accessed by the CGCC team. CGCC shall retain the data in accordance with Document Retention Period and will be deleted upon disposal. By answering this form, you are giving CGCC consent to process and store this information. Please answer carefully and truthfully.', 4, NULL, 1, 300),
(961, 1, 'SOCIAL/EMOTIONAL CONCERNS', 4, NULL, 1, 301),
(962, 1, 'FAMILY & HOME CONCERNS', 4, NULL, 1, 301),
(963, 1, 'MENTAL/PHYSICAL HEALTH CONCERNS', 4, NULL, 1, 301),
(964, 1, 'ACADEMIC CONCERNS', 4, NULL, 1, 301),
(965, 1, 'PROFESSOR ISSUE CONCERNS', 4, NULL, 1, 301),
(966, 1, 'CAREER CONCERNS', 4, NULL, 1, 301),
(967, 1, 'I have other concerns/questions that I want to directly consult or discuss with my counselor.', 3, NULL, 1, 301),
(968, 1, 'We appreciate your feedback. Please let us know how we can best improve our CGCC Student Individual Inventory (SII) Form. If you have comments/suggestions, please indicate them below:', 1, 'text', 1, 301),
(969, 1, 'By submitting this form, I certify that the above information are true and correct. FALSIFICATION of any information will be subjected to DISCIPLINARY ACTION.', 4, NULL, 1, 301),
(970, 1, 'I understand the nature and limits of confidentiality stated above and accept them as part of the benefits and conditions of participating in counseling. In the event that my counselor reasonably believes that there is evidence of clear and imminent danger of harm to myself and/or others, physically or emotionally, I give consent to my counselor to contact the following persons, in addition to the school and medical personnel.', 3, NULL, 1, 303),
(971, 1, 'Name of Father/Mother or Legal Guardian', 1, 'text', 1, 303),
(972, 1, 'Contact number of parent/guardian', 1, 'text', 1, 303),
(973, 1, 'When client information is utilized on outcome research purposes, client names are not disclosed.', 3, NULL, 1, 304),
(974, 1, 'Counseling Guidelines\nPlease review the Counseling Guidelines through this link: https://bit.ly/counselingguide\nBy accomplishing this form you understand and agree to the guidelines set by CGCC.', 8, NULL, 0, 304),
(975, 1, 'This document has provided the information required to address expectations about counseling. I have read and fully understand this document. All questions that I had have been answered to my satisfaction. By filling out this form, I voluntarily agree to accept counseling.', 8, NULL, 0, 304),
(976, 8, 'Counselor being Evaluated', 5, NULL, 1, 305),
(977, 8, 'Please choose the number that corresponds to your level of agreement to the following statements (4 being the HIGHEST and 1 being the LOWEST):', 6, NULL, 1, 306),
(978, 8, 'Please take this opportunity to express your comments and suggestion about your experience with this session. We encourage you to be completely open, as this is the only way we can evaluate ourselves and initiate improvements.', 2, NULL, 0, 306),
(979, 8, 'Thank you!\n\nWe appreciate your comments and feedback.', 8, NULL, 0, 306),
(980, 9, '', 6, NULL, 0, 307),
(981, 9, 'In the past two (2) weeks, have you:', 6, NULL, 0, 307),
(982, 9, 'Sometimes things happen to people that are unusually or especially frightening, horrible, or traumatic. For example a serious accident or fire, a physical or sexual assault or abuse, an earthquake or flood, a war, seeing someone be killed or seriously injured, having a loved one die through homicide or suicide. Have you ever experienced any of this kind of event?', 3, NULL, 0, 307),
(983, 9, 'How would you rate your current level of stress?', 3, NULL, 0, 307),
(984, 9, 'Suicide Risk Screening/Assessment (Please respond to the following items)', 6, NULL, 1, 307),
(985, 9, 'Thanks for answering the questions above. At this point, we would like to know if there are other things that you would like to share or talk about with your counselor.', 2, NULL, 0, 307),
(1022, 11, 'How would you evaluate the overall quality of your college experience at De La Salle Lipa?', 3, NULL, 1, 313),
(1023, 11, 'How satisfied are you with the following aspects that De La Salle Lipa has provided?', 6, NULL, 1, 313),
